// ===================================================================
// INITIALIZATION
// ===================================================================
document.addEventListener('DOMContentLoaded', () => {
  renderCatalogCourses(state.courses);
  renderAdminCoursesTable();
  renderAdminUsersTable();
  initAdminChart();
  renderClassroomUI();
  loadSavedStudentNote();

  // Handle URL hash or default to landing
  const hash = window.location.hash.replace('#', '');
  if (['landing', 'student-dashboard', 'classroom', 'catalog', 'admin-dashboard', 'mobile-preview'].includes(hash)) {
    switchView(hash);
  } else {
    switchView('landing');
  }
});

// ===================================================================
// VIEW SWITCHING (Matches the 6 panels in the design diagram)
// ===================================================================
function switchView(viewName) {
  state.currentView = viewName;
  window.location.hash = viewName;

  // Hide all view containers
  const views = [
    'landing',
    'student-dashboard',
    'classroom',
    'catalog',
    'admin-dashboard',
    'mobile-preview'
  ];

  views.forEach(v => {
    const el = document.getElementById(`view-${v}`);
    if (el) {
      if (v === 'landing' || v === 'classroom' || v === 'catalog' || v === 'mobile-preview') {
        el.style.display = (v === viewName) ? 'block' : 'none';
      } else {
        el.style.display = (v === viewName) ? 'flex' : 'none';
      }
    }

    // Update topbar demo pills
    const pill = document.getElementById(`pill-${v}`);
    if (pill) {
      if (v === viewName) {
        pill.classList.add('active');
      } else {
        pill.classList.remove('active');
      }
    }
  });

  // Re-render chart if switching to admin dashboard
  if (viewName === 'admin-dashboard') {
    setTimeout(() => {
      initAdminChart();
    }, 150);
  }

  // Handle classroom canvas and video on view change
  if (viewName === 'classroom') {
    setTimeout(() => {
      drawStudioCanvas();
      updateSubtitles();
    }, 150);
  } else {
    pauseVideo();
  }

  // Scroll to top
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// Role Toggle between Siswa and Admin
function toggleActiveRole() {
  if (state.currentRole === 'siswa') {
    setRoleAndSwitch('admin');
  } else {
    setRoleAndSwitch('siswa');
  }
}

function setRoleAndSwitch(role) {
  state.currentRole = role;
  const label = document.getElementById('current-role-label');
  const roleBtn = document.getElementById('role-pill-btn');

  if (role === 'admin') {
    state.currentUser = { name: 'Siti Aminah', email: 'admin@eduflex.id', avatar: 'AD', role: 'admin' };
    if (label) label.textContent = 'Admin (Siti)';
    if (roleBtn) {
      roleBtn.style.background = '#854D0E';
      roleBtn.style.borderColor = '#F59E0B';
    }
    showToast('Beralih ke mode Administrator', 'success');
    switchView('admin-dashboard');
  } else {
    state.currentUser = { name: 'Ahmad', email: 'ahmad@eduflex.id', avatar: 'AM', role: 'siswa' };
    if (label) label.textContent = 'Ahmad (Siswa)';
    if (roleBtn) {
      roleBtn.style.background = '#1E293B';
      roleBtn.style.borderColor = '#3B82F6';
    }
    showToast('Beralih ke mode Siswa (Ahmad)', 'success');
    switchView('student-dashboard');
  }
}

