// ===================================================================
// 1. LANDING PAGE LOGIC
// ===================================================================
function filterLandingCategory(cat, btn) {
  // Update active pill styling
  document.querySelectorAll('.landing-search-bar .cat-pill').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  // Filter landing courses cards dynamically in-place
  const cards = document.querySelectorAll('#popular-courses-container .course-card');
  cards.forEach(card => {
    const cardCat = card.querySelector('.course-category-tag')?.textContent.trim() || '';
    if (cat === 'all' || cardCat.toLowerCase() === cat.toLowerCase()) {
      card.style.display = 'flex';
    } else {
      card.style.display = 'none';
    }
  });
}

function handleLandingSearch(e) {
  if (e.key === 'Enter') {
    const query = e.target.value.trim();
    if (query) {
      switchView('catalog');
      const catInput = document.getElementById('catalogSearchInput');
      if (catInput) {
        catInput.value = query;
        filterCatalogCourses();
      }
    }
  }
}

// ===================================================================
// 2. DASHBOARD SISWA LOGIC
// ===================================================================
function handleStudentSearch(e) {
  if (e.key === 'Enter') {
    const q = e.target.value.trim();
    if (q) {
      switchView('catalog');
      const catInput = document.getElementById('catalogSearchInput');
      if (catInput) {
        catInput.value = q;
        filterCatalogCourses();
      }
    }
  }
}

