// ===================================================================
// 3. HALAMAN PEMBELAJARAN (CLASSROOM / VIDEO PLAYER)
// ===================================================================
function openClassroomCourse(courseId) {
  state.classroom.courseId = courseId;
  const course = state.courses.find(c => c.id === courseId) || state.courses[0];

  const titleEl = document.getElementById('classroom-course-title');
  if (titleEl) titleEl.textContent = course.title;

  switchView('classroom');
  renderClassroomUI();
}

function renderClassroomUI() {
  const currentLesson = state.classroom.lessons.find(l => l.id === state.classroom.currentLessonId) || state.classroom.lessons[1];

  // Update Lesson Title & Description
  const titleEl = document.getElementById('currentLessonTitle');
  const descEl = document.getElementById('currentLessonDesc');
  const modulBadge = document.getElementById('classroom-modul-badge');

  if (titleEl) titleEl.textContent = currentLesson.title.replace(/^\d+\.\s*/, '');
  if (descEl) descEl.textContent = currentLesson.desc;
  if (modulBadge) modulBadge.textContent = `Modul ${currentLesson.id} dari ${state.classroom.lessons.length}`;

  // Update Syllabus List Items
  const listEl = document.getElementById('syllabusItemsList');
  if (listEl) {
    listEl.innerHTML = '';
    state.classroom.lessons.forEach(lesson => {
      const li = document.createElement('li');
      li.className = `syllabus-item ${lesson.id === state.classroom.currentLessonId ? 'active' : ''}`;
      li.onclick = () => selectLesson(lesson.id);

      let badgeHtml = '';
      if (lesson.status === 'completed') {
        badgeHtml = `<span class="syllabus-status-badge badge-completed"><i class="fa-solid fa-check"></i> Selesai</span>`;
      } else if (lesson.id === state.classroom.currentLessonId) {
        badgeHtml = `<span class="syllabus-status-badge badge-learning"><i class="fa-solid fa-play"></i> Sedang Dipelajari</span>`;
      } else {
        badgeHtml = `<span class="syllabus-status-badge badge-pending">Belum Selesai</span>`;
      }

      li.innerHTML = `
        <div class="syllabus-item-title">${lesson.title}</div>
        ${badgeHtml}
      `;
      listEl.appendChild(li);
    });
  }

  // Update Mark Complete Button
  const btnMark = document.getElementById('btnMarkComplete');
  const markLabel = document.getElementById('markCompleteLabel');
  if (btnMark && markLabel) {
    if (currentLesson.status === 'completed') {
      btnMark.className = 'btn-outline-edu';
      btnMark.innerHTML = '<i class="fa-solid fa-check-double text-success"></i> Selesai Dipelajari';
    } else {
      btnMark.className = 'btn-primary-edu';
      btnMark.innerHTML = '<i class="fa-solid fa-check"></i> Mark as Complete';
    }
  }

  // Update Prev / Next Buttons state
  const prevBtn = document.getElementById('btnPrevLesson');
  const nextBtn = document.getElementById('btnNextLesson');
  if (prevBtn) prevBtn.disabled = (state.classroom.currentLessonId === 1);
  if (nextBtn) nextBtn.disabled = (state.classroom.currentLessonId === state.classroom.lessons.length);

  // Update video duration & reset scrub
  state.video.currentTime = 0;
  const currentBadge = document.getElementById('videoBadgeTopic');
  if (currentBadge) {
    currentBadge.textContent = `Modul ${currentLesson.id} • ${currentLesson.title.replace(/^\d+\.\s*/, '')}`;
  }
  updateVideoControlsUI();
  updateSubtitles();
  drawStudioCanvas();
}

function selectLesson(lessonId) {
  state.classroom.currentLessonId = lessonId;
  const lesson = state.classroom.lessons.find(l => l.id === lessonId);
  if (lesson) {
    state.video.duration = lesson.durationSec || 765;
    state.video.currentTime = 0;

    // Update HTML5 video element source
    const html5 = document.getElementById('actualHtml5Video');
    if (html5 && lesson.videoUrl) {
      html5.src = lesson.videoUrl;
    }

    // Update YouTube Iframe if active
    const ytIframe = document.getElementById('youtubeIframe');
    if (ytIframe && state.video.mode === 'youtube' && lesson.youtubeId) {
      ytIframe.src = `https://www.youtube-nocookie.com/embed/${lesson.youtubeId}?autoplay=1&rel=0`;
    }
  }

  pauseVideo();
  renderClassroomUI();
  drawStudioCanvas();
  updateSubtitles();
  showToast(`Membuka materi: ${lesson ? lesson.title : ''}`, 'info');
}

function navigateLesson(delta) {
  const newId = state.classroom.currentLessonId + delta;
  if (newId >= 1 && newId <= state.classroom.lessons.length) {
    selectLesson(newId);
  }
}

function toggleLessonComplete() {
  const current = state.classroom.lessons.find(l => l.id === state.classroom.currentLessonId);
  if (!current) return;

  if (current.status === 'completed') {
    current.status = 'learning';
    showToast('Status materi diubah menjadi belum selesai', 'info');
  } else {
    current.status = 'completed';
    showToast(`Hebat! Materi "${current.title}" telah diselesaikan!`, 'success');

    // Trigger slight confetti burst
    if (typeof confetti === 'function') {
      confetti({
        particleCount: 40,
        spread: 60,
        origin: { y: 0.7 }
      });
    }

    // Recalculate progress
    recalcProgress();
  }

  renderClassroomUI();
}

function recalcProgress() {
  const completed = state.classroom.lessons.filter(l => l.status === 'completed').length;
  const total = state.classroom.lessons.length;
  const pct = Math.round((completed / total) * 100);

  // Update continue course card progress
  const bar = document.getElementById('continue-course-bar');
  const txt = document.getElementById('continue-course-pct');
  const dashPct = document.getElementById('dash-progress-pct');

  if (bar) bar.style.width = `${pct}%`;
  if (txt) txt.textContent = `${pct}% completed`;
  if (dashPct) dashPct.textContent = `${Math.max(pct, 85)}%`;

  if (completed === total) {
    showToast('Selamat! Semua materi telah selesai. Kamu bisa klaim sertifikat sekarang!', 'success');
  }
}

// ===================================================================
// VIDEO PLAYER ENGINE (STUDIO CANVAS, HTML5 MP4 & YOUTUBE STREAMING)
// ===================================================================

function setVideoMode(mode) {
  state.video.mode = mode;

  const canvasScreen = document.getElementById('lessonCanvasScreen');
  const html5Screen = document.getElementById('actualHtml5Video');
  const ytContainer = document.getElementById('youtubePlayerContainer');
  const ytIframe = document.getElementById('youtubeIframe');

  const btnStudio = document.getElementById('btnModeStudio');
  const btnHtml5 = document.getElementById('btnModeHtml5');
  const btnYoutube = document.getElementById('btnModeYoutube');

  [btnStudio, btnHtml5, btnYoutube].forEach(b => { if (b) b.classList.remove('active'); });

  const lesson = state.classroom.lessons.find(l => l.id === state.classroom.currentLessonId) || state.classroom.lessons[1];

  if (mode === 'studio') {
    if (btnStudio) btnStudio.classList.add('active');
    if (canvasScreen) canvasScreen.style.display = 'block';
    if (html5Screen) {
      html5Screen.style.display = 'none';
      html5Screen.pause();
    }
    if (ytContainer) ytContainer.style.display = 'none';
    showToast('Beralih ke: Studio Simulasi Interaktif UI/UX (60 FPS)', 'info');
    drawStudioCanvas();
  } else if (mode === 'html5') {
    if (btnHtml5) btnHtml5.classList.add('active');
    if (canvasScreen) canvasScreen.style.display = 'none';
    if (html5Screen) {
      html5Screen.style.display = 'block';
      if (lesson.videoUrl && (!html5Screen.src || !html5Screen.src.includes(lesson.videoUrl))) {
        html5Screen.src = lesson.videoUrl;
        html5Screen.load();
      }
    }
    if (ytContainer) ytContainer.style.display = 'none';
    showToast('Beralih ke: Video Web MP4 Cloud', 'info');
  } else if (mode === 'youtube') {
    if (btnYoutube) btnYoutube.classList.add('active');
    if (canvasScreen) canvasScreen.style.display = 'none';
    if (html5Screen) {
      html5Screen.style.display = 'none';
      html5Screen.pause();
    }
    if (ytContainer) {
      ytContainer.style.display = 'block';
      const yId = lesson.youtubeId || 'c9Wg6Cb_YlU';
      if (ytIframe && (!ytIframe.src || !ytIframe.src.includes(yId))) {
        ytIframe.src = `https://www.youtube-nocookie.com/embed/${yId}?autoplay=1&rel=0`;
      }
    }
    showToast('Beralih ke: YouTube UI/UX Official Course', 'info');
  }
}

function toggleSubtitles() {
  state.video.subtitlesEnabled = !state.video.subtitlesEnabled;
  const btn = document.getElementById('btnToggleSubtitles');
  const text = document.getElementById('subtitlesBtnText');
  if (btn) {
    if (state.video.subtitlesEnabled) {
      btn.classList.add('active');
      if (text) text.textContent = 'CC On';
      showToast('Teks subtitle diaktifkan', 'info');
    } else {
      btn.classList.remove('active');
      if (text) text.textContent = 'CC Off';
      showToast('Teks subtitle dimatikan', 'info');
    }
  }
  updateSubtitles();
}

function updateSubtitles() {
  const subTextEl = document.getElementById('videoSubtitleText');
  const subOverlay = document.getElementById('videoSubtitleOverlay');
  if (!subTextEl || !subOverlay) return;

  if (!state.video.subtitlesEnabled) {
    subOverlay.style.opacity = '0';
    return;
  }
  subOverlay.style.opacity = '1';

  const lesson = state.classroom.lessons.find(l => l.id === state.classroom.currentLessonId) || state.classroom.lessons[1];
  if (!lesson || !lesson.subtitles || lesson.subtitles.length === 0) return;

  const t = Math.floor(state.video.currentTime);
  let currentSub = lesson.subtitles[0].text;
  for (let i = 0; i < lesson.subtitles.length; i++) {
    if (t >= lesson.subtitles[i].time) {
      currentSub = lesson.subtitles[i].text;
    }
  }

  if (subTextEl.textContent !== currentSub) {
    subTextEl.textContent = currentSub;
    if (state.video.isPlaying && !state.video.isMuted) {
      playSynthesizedLectureTone();
    }
  }
}

function playSynthesizedLectureTone() {
  if (state.video.isMuted) return;
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    if (!state.video.audioCtx) {
      state.video.audioCtx = new AudioCtx();
    }
    const ctx = state.video.audioCtx;
    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    const notes = [329.63, 392.00, 493.88, 587.33];
    const note = notes[Math.floor(Math.random() * notes.length)];
    osc.frequency.setValueAtTime(note, ctx.currentTime);

    gain.gain.setValueAtTime(0.03, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.8);

    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start();
    osc.stop(ctx.currentTime + 0.8);
  } catch (e) {
    // Gracefully ignore audio context blocks
  }
}

function roundRect(ctx, x, y, width, height, radius) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + width - radius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
  ctx.lineTo(x + width, y + height - radius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
}

function roundRectTop(ctx, x, y, width, height, radius) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + width - radius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
  ctx.lineTo(x + width, y + height);
  ctx.lineTo(x, y + height);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
}

// 60 FPS Visual Studio Canvas Renderer
function drawStudioCanvas() {
  const canvas = document.getElementById('lessonCanvasScreen');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;
  const t = state.video.currentTime;

  // Clear dark background
  ctx.fillStyle = '#0F172A';
  ctx.fillRect(0, 0, w, h);

  // Subtle grid background (Figma Artboard style)
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
  ctx.lineWidth = 1;
  const gridSize = 32;
  for (let x = 0; x < w; x += gridSize) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, h);
    ctx.stroke();
  }
  for (let y = 0; y < h; y += gridSize) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(w, y);
    ctx.stroke();
  }

  const lesson = state.classroom.lessons.find(l => l.id === state.classroom.currentLessonId) || state.classroom.lessons[1];

  // Draw Main Artboard Mockup (Left Side)
  const artX = 40;
  const artY = 40;
  const artW = 480;
  const artH = 450;

  // Artboard Shadow & Container
  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.45)';
  ctx.shadowBlur = 24;
  ctx.shadowOffsetY = 10;
  ctx.fillStyle = '#1E293B';
  roundRect(ctx, artX, artY, artW, artH, 16);
  ctx.fill();
  ctx.restore();

  // Artboard Header Bar
  ctx.fillStyle = '#334155';
  roundRectTop(ctx, artX, artY, artW, 40, 16);
  ctx.fill();

  // macOS / Figma traffic lights
  ctx.fillStyle = '#EF4444';
  ctx.beginPath(); ctx.arc(artX + 20, artY + 20, 5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#F59E0B';
  ctx.beginPath(); ctx.arc(artX + 36, artY + 20, 5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#10B981';
  ctx.beginPath(); ctx.arc(artX + 52, artY + 20, 5, 0, Math.PI * 2); ctx.fill();

  ctx.fillStyle = '#F1F5F9';
  ctx.font = '600 13px Poppins, sans-serif';
  ctx.fillText(`Figma Canvas • ${lesson.title}`, artX + 75, artY + 24);

  // Content inside Artboard
  const cardX = artX + 24;
  const cardY = artY + 56;
  const cardW = artW - 48;
  const cardH = 370;

  ctx.fillStyle = '#FFFFFF';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12);
  ctx.fill();

  // Inner Mockup Content
  ctx.fillStyle = '#0F172A';
  ctx.font = '700 15px Poppins, sans-serif';
  ctx.fillText('EDUFLEX Platform App', cardX + 20, cardY + 34);

  ctx.fillStyle = '#64748B';
  ctx.font = '500 11px Inter, sans-serif';
  ctx.fillText('Digital Education Ecosystem (UI/UX Blueprint)', cardX + 20, cardY + 50);

  // Hero Banner in Mockup
  const heroGrad = ctx.createLinearGradient(cardX + 20, cardY + 64, cardX + cardW - 20, cardY + 160);
  heroGrad.addColorStop(0, '#2563EB');
  heroGrad.addColorStop(1, '#7C3AED');
  ctx.fillStyle = heroGrad;
  roundRect(ctx, cardX + 20, cardY + 64, cardW - 40, 100, 10);
  ctx.fill();

  ctx.fillStyle = '#FFFFFF';
  ctx.font = '700 15px Poppins, sans-serif';
  ctx.fillText('Learn Without Limits', cardX + 34, cardY + 98);
  ctx.fillStyle = '#E2E8F0';
  ctx.font = '400 11px Inter, sans-serif';
  ctx.fillText('Master Digital Skills with Expert Guidance.', cardX + 34, cardY + 118);
  ctx.fillText('Responsive • Interactive • Certified', cardX + 34, cardY + 136);

  // 3 Mini Cards in Mockup
  const miniW = (cardW - 40 - 16) / 3;
  const cats = ['UI/UX', 'Python', 'Marketing'];
  const colors = ['#2563EB', '#F59E0B', '#10B981'];

  for (let i = 0; i < 3; i++) {
    const mx = cardX + 20 + i * (miniW + 8);
    const my = cardY + 178;
    ctx.fillStyle = '#F8FAFC';
    ctx.strokeStyle = '#E2E8F0';
    ctx.lineWidth = 1;
    roundRect(ctx, mx, my, miniW, 85, 8);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = colors[i];
    ctx.fillRect(mx + 10, my + 10, 26, 6);

    ctx.fillStyle = '#0F172A';
    ctx.font = '700 11px Poppins, sans-serif';
    ctx.fillText(cats[i], mx + 10, my + 36);

    ctx.fillStyle = '#64748B';
    ctx.font = '500 9px Inter, sans-serif';
    ctx.fillText('⭐ 4.9 • 12 Mtr', mx + 10, my + 54);
    ctx.fillStyle = '#2563EB';
    ctx.fillText('View →', mx + 10, my + 72);
  }

  // Interactive Call to Action Button in Mockup
  const btnX = cardX + 20;
  const btnY = cardY + 282;
  const btnW = cardW - 40;
  const btnH = 44;

  ctx.fillStyle = '#2563EB';
  roundRect(ctx, btnX, btnY, btnW, btnH, 8);
  ctx.fill();

  ctx.fillStyle = '#FFFFFF';
  ctx.font = '600 13px Poppins, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('Mulai Belajar Sekarang (CTA Active) →', btnX + btnW / 2, btnY + 27);
  ctx.textAlign = 'left';

  // Draw Right Panel: Teacher Webcam & Design System Inspector
  const rightX = 550;
  const rightW = 370;

  // Teacher Video Webcam Card (Top Right)
  const camY = 40;
  const camH = 150;
  ctx.fillStyle = '#1E293B';
  ctx.strokeStyle = '#3B82F6';
  ctx.lineWidth = 2;
  roundRect(ctx, rightX, camY, rightW, camH, 14);
  ctx.fill();
  ctx.stroke();

  // Webcam live badge
  ctx.fillStyle = '#EF4444';
  ctx.beginPath(); ctx.arc(rightX + 24, camY + 24, 5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#F8FAFC';
  ctx.font = '700 11px Inter, sans-serif';
  ctx.fillText('LIVE RECORDING', rightX + 36, camY + 28);

  // Instructor Avatar Circle
  const avX = rightX + 60;
  const avY = camY + 84;
  ctx.fillStyle = '#2563EB';
  ctx.beginPath(); ctx.arc(avX, avY, 32, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = '#60A5FA';
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.fillStyle = '#FFFFFF';
  ctx.beginPath(); ctx.arc(avX, avY - 6, 12, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(avX, avY + 22, 20, Math.PI * 1.1, Math.PI * 1.9); ctx.fill();

  ctx.fillStyle = '#FFFFFF';
  ctx.font = '700 14px Poppins, sans-serif';
  ctx.fillText('Ahmad Fauzi', rightX + 110, camY + 76);
  ctx.fillStyle = '#94A3B8';
  ctx.font = '500 11px Inter, sans-serif';
  ctx.fillText('Principal Product Designer', rightX + 110, camY + 94);

  // Equalizer Bars (moving when isPlaying)
  ctx.fillStyle = '#10B981';
  for (let b = 0; b < 6; b++) {
    const eqH = state.video.isPlaying ? (Math.sin(t * 8 + b * 1.2) * 8 + 12) : 4;
    ctx.fillRect(rightX + 110 + b * 10, camY + 110 - eqH / 2, 6, eqH);
  }
  ctx.fillStyle = '#34D399';
  ctx.font = '600 10px Inter, sans-serif';
  ctx.fillText(state.video.isPlaying ? 'Speaking (Live Audio)' : 'Paused', rightX + 180, camY + 114);

  // Design Inspector Panel (Bottom Right)
  const specY = 210;
  const specH = 280;
  ctx.fillStyle = '#1E293B';
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
  ctx.lineWidth = 1;
  roundRect(ctx, rightX, specY, rightW, specH, 14);
  ctx.fill();
  ctx.stroke();

  ctx.fillStyle = '#60A5FA';
  ctx.font = '700 12px Poppins, sans-serif';
  ctx.fillText('DESIGN SYSTEM & PRINCIPLES', rightX + 20, specY + 30);

  // Color Swatches
  const swatches = [
    { name: 'Primary', hex: '#2563EB' },
    { name: 'Accent', hex: '#7C3AED' },
    { name: 'Dark', hex: '#0F172A' },
    { name: 'Success', hex: '#10B981' }
  ];

  ctx.fillStyle = '#94A3B8';
  ctx.font = '500 11px Inter, sans-serif';
  ctx.fillText('Color Palette Tokens:', rightX + 20, specY + 54);

  swatches.forEach((sw, idx) => {
    const sx = rightX + 20 + idx * 82;
    const sy = specY + 64;
    ctx.fillStyle = sw.hex;
    roundRect(ctx, sx, sy, 22, 22, 6);
    ctx.fill();
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.fillStyle = '#F8FAFC';
    ctx.font = '600 10px Inter, sans-serif';
    ctx.fillText(sw.name, sx + 28, sy + 15);
  });

  // Principles Checklist
  ctx.fillStyle = '#94A3B8';
  ctx.font = '500 11px Inter, sans-serif';
  ctx.fillText('Evaluasi Parameter UI/UX:', rightX + 20, specY + 116);

  const principles = [
    'Visual Hierarchy & Weight',
    'Consistency (8pt Spacing Grid)',
    'Accessibility & Contrast AA',
    'Responsive Fluid Breakpoints'
  ];

  principles.forEach((p, idx) => {
    const py = specY + 140 + idx * 26;
    const isHighlighted = (Math.floor(t / 4) % 4) === idx;

    ctx.fillStyle = isHighlighted ? 'rgba(37, 99, 235, 0.25)' : 'transparent';
    if (isHighlighted) {
      roundRect(ctx, rightX + 16, py - 14, rightW - 32, 24, 6);
      ctx.fill();
    }

    ctx.fillStyle = isHighlighted ? '#60A5FA' : '#10B981';
    ctx.font = '700 12px sans-serif';
    ctx.fillText('✔', rightX + 24, py + 2);

    ctx.fillStyle = isHighlighted ? '#FFFFFF' : '#CBD5E1';
    ctx.font = `${isHighlighted ? '700' : '500'} 11px Inter, sans-serif`;
    ctx.fillText(p, rightX + 44, py + 2);
  });

  // Code snippet preview in inspector
  ctx.fillStyle = '#0F172A';
  roundRect(ctx, rightX + 20, specY + 238, rightW - 40, 26, 6);
  ctx.fill();
  ctx.fillStyle = '#38BDF8';
  ctx.font = '10px monospace';
  ctx.fillText(`.btn-cta { background: #2563EB; border-radius: 8px; }`, rightX + 28, specY + 254);

  // Animated Teacher's Mouse Pointer
  const targetPoints = [
    { x: cardX + 120, y: cardY + 34 },
    { x: cardX + 160, y: cardY + 110 },
    { x: btnX + btnW / 2, y: btnY + 22 },
    { x: rightX + 60, y: specY + 74 },
    { x: rightX + 100, y: specY + 160 }
  ];
  const cycle = (t * 0.4) % targetPoints.length;
  const pIdx = Math.floor(cycle);
  const pNext = (pIdx + 1) % targetPoints.length;
  const frac = cycle - pIdx;
  const easeFrac = 0.5 - 0.5 * Math.cos(frac * Math.PI);

  const curX = targetPoints[pIdx].x + (targetPoints[pNext].x - targetPoints[pIdx].x) * easeFrac;
  const curY = targetPoints[pIdx].y + (targetPoints[pNext].y - targetPoints[pIdx].y) * easeFrac;

  // Button Ripple on click
  if (pIdx === 2 && frac > 0.4 && frac < 0.8) {
    const ripR = (frac - 0.4) * 50;
    ctx.strokeStyle = `rgba(37, 99, 235, ${1 - (frac - 0.4) / 0.4})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(curX, curY, ripR, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Draw Cursor Arrow
  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
  ctx.shadowBlur = 8;
  ctx.shadowOffsetY = 3;
  ctx.fillStyle = '#FFFFFF';
  ctx.strokeStyle = '#0F172A';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(curX, curY);
  ctx.lineTo(curX, curY + 18);
  ctx.lineTo(curX + 5, curY + 14);
  ctx.lineTo(curX + 10, curY + 22);
  ctx.lineTo(curX + 13, curY + 20);
  ctx.lineTo(curX + 8, curY + 12);
  ctx.lineTo(curX + 14, curY + 12);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // User badge on cursor
  ctx.fillStyle = '#2563EB';
  roundRect(ctx, curX + 14, curY + 16, 52, 18, 9);
  ctx.fill();
  ctx.fillStyle = '#FFFFFF';
  ctx.font = '600 9px Inter, sans-serif';
  ctx.fillText('Ahmad', curX + 22, curY + 29);
  ctx.restore();
}

// Play / Pause Video
function togglePlayVideo() {
  if (state.video.isPlaying) {
    pauseVideo();
  } else {
    playVideo();
  }
}

function playVideo() {
  state.video.isPlaying = true;
  const centralBtn = document.getElementById('centralPlayBtn');
  const ctrlIcon = document.getElementById('ctrlPlayIcon');
  if (centralBtn) centralBtn.style.display = 'none';
  if (ctrlIcon) ctrlIcon.className = 'fa-solid fa-pause';

  // If in HTML5 mode
  if (state.video.mode === 'html5') {
    const html5 = document.getElementById('actualHtml5Video');
    if (html5) {
      html5.playbackRate = state.video.playbackRate;
      html5.muted = state.video.isMuted;
      html5.play().catch(err => {
        console.warn('HTML5 Video play error:', err);
        showToast('Video MP4 tidak dapat dimuat, beralih ke Studio Simulasi UI/UX', 'warning');
        setVideoMode('studio');
      });
    }
  }

  // Animation Loop & Timer
  cancelAnimationFrame(state.video.animFrame);
  clearInterval(state.video.timer);

  let lastTimestamp = performance.now();
  function loop(now) {
    if (!state.video.isPlaying) return;
    const deltaSec = (now - lastTimestamp) / 1000;
    lastTimestamp = now;

    if (state.video.mode === 'studio') {
      state.video.currentTime += deltaSec * state.video.playbackRate;
      if (state.video.currentTime >= state.video.duration) {
        state.video.currentTime = state.video.duration;
        pauseVideo();
      }
      drawStudioCanvas();
      updateSubtitles();
      updateVideoControlsUI();
    } else if (state.video.mode === 'html5') {
      const html5 = document.getElementById('actualHtml5Video');
      if (html5 && !html5.paused) {
        state.video.currentTime = html5.currentTime;
        if (html5.duration && !isNaN(html5.duration)) {
          state.video.duration = html5.duration;
        }
        updateSubtitles();
        updateVideoControlsUI();
      }
    }

    state.video.animFrame = requestAnimationFrame(loop);
  }
  state.video.animFrame = requestAnimationFrame(loop);
}

function pauseVideo() {
  state.video.isPlaying = false;
  cancelAnimationFrame(state.video.animFrame);
  clearInterval(state.video.timer);

  const centralBtn = document.getElementById('centralPlayBtn');
  const ctrlIcon = document.getElementById('ctrlPlayIcon');
  if (centralBtn) centralBtn.style.display = 'flex';
  if (ctrlIcon) ctrlIcon.className = 'fa-solid fa-play';

  if (state.video.mode === 'html5') {
    const html5 = document.getElementById('actualHtml5Video');
    if (html5) html5.pause();
  }

  if (state.video.mode === 'studio') {
    drawStudioCanvas();
  }
}

function updateVideoControlsUI() {
  const fill = document.getElementById('timelineFilled');
  const timeDisp = document.getElementById('videoTimeDisplay');

  const curSec = Math.floor(state.video.currentTime);
  const durSec = state.video.duration;

  if (fill) {
    const pct = Math.min(100, Math.max(0, (curSec / durSec) * 100));
    fill.style.width = `${pct}%`;
  }

  if (timeDisp) {
    const cM = Math.floor(curSec / 60);
    const cS = curSec % 60;
    const dM = Math.floor(durSec / 60);
    const dS = durSec % 60;
    timeDisp.textContent = `${cM}:${cS < 10 ? '0' : ''}${cS} / ${dM}:${dS < 10 ? '0' : ''}${dS}`;
  }
}

function handleScrub(e) {
  const scrubber = document.getElementById('timelineScrubber');
  if (!scrubber) return;
  const rect = scrubber.getBoundingClientRect();
  const clickX = e.clientX - rect.left;
  const pct = Math.max(0, Math.min(1, clickX / rect.width));
  state.video.currentTime = pct * state.video.duration;

  if (state.video.mode === 'html5') {
    const html5 = document.getElementById('actualHtml5Video');
    if (html5) html5.currentTime = state.video.currentTime;
  }

  if (state.video.mode === 'studio') {
    drawStudioCanvas();
    updateSubtitles();
  }

  updateVideoControlsUI();
}

function toggleMuteVideo() {
  state.video.isMuted = !state.video.isMuted;
  const icon = document.getElementById('ctrlVolumeIcon');
  if (icon) {
    icon.className = state.video.isMuted ? 'fa-solid fa-volume-xmark' : 'fa-solid fa-volume-high';
  }

  const html5 = document.getElementById('actualHtml5Video');
  if (html5) html5.muted = state.video.isMuted;

  showToast(state.video.isMuted ? 'Suara dibisukan' : 'Suara aktif', 'info');
}

function cyclePlaybackRate() {
  const rates = [1, 1.25, 1.5, 2];
  const curIdx = rates.indexOf(state.video.playbackRate);
  const nextRate = rates[(curIdx + 1) % rates.length];
  state.video.playbackRate = nextRate;

  const btn = document.getElementById('speedBtn');
  if (btn) btn.textContent = `${nextRate}x`;

  const html5 = document.getElementById('actualHtml5Video');
  if (html5) html5.playbackRate = nextRate;

  showToast(`Kecepatan video: ${nextRate}x`, 'info');
}

function toggleFullScreenPlayer() {
  const frame = document.getElementById('mainVideoPlayer');
  if (!document.fullscreenElement) {
    if (frame.requestFullscreen) {
      frame.requestFullscreen();
    } else if (frame.webkitRequestFullscreen) {
      frame.webkitRequestFullscreen();
    }
  } else {
    if (document.exitFullscreen) {
      document.exitFullscreen();
    } else if (document.webkitExitFullscreen) {
      document.webkitExitFullscreen();
    }
  }
}

// Student Study Tabs (Notes, Summary, AI Assistant)
function switchStudyTab(tabName, btn) {
  ['notes', 'summary', 'ai'].forEach(t => {
    const el = document.getElementById(`studyTab-${t}`);
    if (el) el.style.display = (t === tabName) ? 'block' : 'none';
  });

  if (btn && btn.parentElement) {
    btn.parentElement.querySelectorAll('button').forEach(b => {
      b.classList.remove('active');
      b.style.color = 'var(--text-body)';
      b.style.fontWeight = '600';
    });
    btn.classList.add('active');
    btn.style.color = 'var(--primary)';
    btn.style.fontWeight = '700';
  }
}

function saveStudentNote(manual = false) {
  const txt = document.getElementById('studentNoteArea').value;
  const key = `eduflex_note_${state.classroom.currentLessonId}`;
  localStorage.setItem(key, txt);

  const status = document.getElementById('noteSaveStatus');
  if (status) {
    status.innerHTML = '<i class="fa-solid fa-check text-success"></i> Catatan tersimpan!';
    setTimeout(() => {
      status.innerHTML = '<i class="fa-solid fa-cloud-arrow-up"></i> Otomatis tersimpan ke memori';
    }, 2000);
  }

  if (manual) {
    showToast('Catatan materi berhasil disimpan!', 'success');
  }
}

function loadSavedStudentNote() {
  const noteArea = document.getElementById('studentNoteArea');
  if (!noteArea) return;
  const key = `eduflex_note_${state.classroom.currentLessonId}`;
  noteArea.value = localStorage.getItem(key) || 'Prinsip desain: Hierarchy, Alignment, Contrast, Proximity, Balance. Desain yang baik mengutamakan kejelasan fungsi bagi pengguna.';
}

function sendAiQuestion() {
  const input = document.getElementById('aiInputPrompt');
  const chatBox = document.getElementById('aiChatBox');
  if (!input || !chatBox) return;

  const q = input.value.trim();
  if (!q) return;

  // Append user message
  const userMsg = document.createElement('div');
  userMsg.style.marginBottom = '8px';
  userMsg.style.textAlign = 'right';
  userMsg.innerHTML = `<span style="background:var(--primary); color:#FFF; padding:6px 12px; border-radius:12px; display:inline-block; font-size:0.82rem;">${q}</span>`;
  chatBox.appendChild(userMsg);
  input.value = '';

  // Simulate AI Response
  setTimeout(() => {
    const aiMsg = document.createElement('div');
    aiMsg.style.marginBottom = '8px';
    aiMsg.innerHTML = `
      <span style="color:#7C3AED; font-weight:700;"><i class="fa-solid fa-robot"></i> EDUFLEX AI:</span>
      <p style="margin-top:2px;">Pertanyaan menarik! Dalam prinsip UI/UX, kunci terpenting adalah konsistensi dan kontras yang jelas agar pengguna tidak perlu berpikir keras (cognitive load minimal). Pastikan tombol aksi utama memiliki bobot visual tertinggi.</p>
    `;
    chatBox.appendChild(aiMsg);
    chatBox.scrollTop = chatBox.scrollHeight;
  }, 700);
}

