// 4. KATALOG KURSUS LOGIC (COURSES EXPLORER)
// ===================================================================
function renderCatalogCourses(coursesList) {
  const grid = document.getElementById('catalogCoursesGrid');
  if (!grid) return;

  grid.innerHTML = '';
  if (coursesList.length === 0) {
    grid.innerHTML = `
      <div style="grid-column: 1/-1; text-align:center; padding:50px 20px; background:#FFF; border-radius:16px;">
        <i class="fa-solid fa-magnifying-glass" style="font-size:2.5rem; color:#CBD5E1; margin-bottom:12px;"></i>
        <h3>Tidak ada kursus yang cocok</h3>
        <p style="color:var(--text-muted); font-size:0.9rem;">Coba ubah kata kunci pencarian atau pilih kategori lain.</p>
      </div>
    `;
    return;
  }

  coursesList.forEach(course => {
    const card = document.createElement('div');
    card.className = 'edu-card course-card';
    card.innerHTML = `
      <div class="course-thumb-box">
        <img src="${course.thumb}" alt="${course.title}">
        <span class="course-category-tag">${course.category}</span>
      </div>
      <div class="course-card-body">
        <h3 class="course-card-title">${course.title}</h3>
        <p class="course-card-author">By ${course.author}</p>
        <div class="course-card-meta">
          <span class="course-rating"><i class="fa-solid fa-star"></i> ${course.rating}</span>
          <span class="course-lessons-count"><i class="fa-regular fa-circle-play"></i> ${course.lessonsCount} materi</span>
        </div>
        <button class="btn-primary-edu btn-view-course" onclick="openClassroomCourse('${course.id}')">
          View Course
        </button>
      </div>
    `;
    grid.appendChild(card);
  });
}

function filterCatalogCourses(explicitCat) {
  const searchInput = document.getElementById('catalogSearchInput');
  const sortSelect = document.getElementById('catalogSortSelect');

  const query = searchInput ? searchInput.value.toLowerCase().trim() : '';
  const sort = sortSelect ? sortSelect.value : 'popular';

  // Safely resolve active category
  const activePill = document.querySelector('.catalog-cat-pills .cat-pill.active');
  let cat = explicitCat || '';
  if (!cat && activePill) {
    const txt = activePill.textContent.trim();
    if (txt.includes('Semua')) {
      cat = 'Semua';
    } else if (txt.includes('Programming')) {
      cat = 'Programming';
    } else if (txt.includes('Design')) {
      cat = 'Design';
    } else if (txt.includes('Marketing')) {
      cat = 'Marketing';
    } else if (txt.includes('Business')) {
      cat = 'Business';
    } else {
      cat = 'Semua';
    }
  }
  if (!cat) cat = 'Semua';

  let filtered = state.courses.filter(c => {
    const matchSearch = c.title.toLowerCase().includes(query) || c.author.toLowerCase().includes(query) || c.category.toLowerCase().includes(query);
    const matchCat = (cat === 'Semua') || (c.category.toLowerCase() === cat.toLowerCase());
    return matchSearch && matchCat;
  });

  // Sort
  if (sort === 'rating') {
    filtered.sort((a, b) => b.rating - a.rating);
  } else if (sort === 'lessons') {
    filtered.sort((a, b) => b.lessonsCount - a.lessonsCount);
  } else if (sort === 'az') {
    filtered.sort((a, b) => a.title.localeCompare(b.title));
  } else {
    filtered.sort((a, b) => (b.isPopular ? 1 : 0) - (a.isPopular ? 1 : 0));
  }

  renderCatalogCourses(filtered);
}

function filterCatalogByCategory(cat, btn) {
  // If btn is not provided, locate the corresponding pill element
  if (!btn) {
    document.querySelectorAll('.catalog-cat-pills .cat-pill').forEach(b => {
      if (b.textContent.toLowerCase().includes(cat.toLowerCase())) {
        btn = b;
      }
    });
  }

  document.querySelectorAll('.catalog-cat-pills .cat-pill').forEach(b => b.classList.remove('active'));
  if (btn) {
    btn.classList.add('active');
  } else {
    const first = document.querySelector('.catalog-cat-pills .cat-pill');
    if (first) first.classList.add('active');
  }

  filterCatalogCourses(cat);
}

