// Admin Course CRUD
function openAddCourseModal() {
  document.getElementById('adminCourseModalTitle').textContent = 'Tambah Kursus Baru';
  document.getElementById('editCourseId').value = '';
  document.getElementById('courseInputTitle').value = '';
  document.getElementById('courseInputAuthor').value = '';
  document.getElementById('courseInputCategory').value = 'Programming';
  document.getElementById('courseInputLessons').value = 12;
  document.getElementById('courseInputRating').value = 4.8;

  const modal = document.getElementById('adminCourseModal');
  if (modal) modal.classList.add('show');
}

function openEditCourseModal(courseId) {
  const c = state.courses.find(item => item.id === courseId);
  if (!c) return;

  document.getElementById('adminCourseModalTitle').textContent = 'Edit Kursus';
  document.getElementById('editCourseId').value = c.id;
  document.getElementById('courseInputTitle').value = c.title;
  document.getElementById('courseInputAuthor').value = c.author;
  document.getElementById('courseInputCategory').value = c.category;
  document.getElementById('courseInputLessons').value = c.lessonsCount;
  document.getElementById('courseInputRating').value = c.rating;

  const modal = document.getElementById('adminCourseModal');
  if (modal) modal.classList.add('show');
}

function closeAdminCourseModal() {
  const modal = document.getElementById('adminCourseModal');
  if (modal) modal.classList.remove('show');
}

function handleSaveCourse(e) {
  e.preventDefault();
  const editId = document.getElementById('editCourseId').value;
  const title = document.getElementById('courseInputTitle').value;
  const author = document.getElementById('courseInputAuthor').value;
  const category = document.getElementById('courseInputCategory').value;
  const lessons = parseInt(document.getElementById('courseInputLessons').value) || 10;
  const rating = parseFloat(document.getElementById('courseInputRating').value) || 4.8;

  if (editId) {
    // Update existing
    const idx = state.courses.findIndex(c => c.id === editId);
    if (idx !== -1) {
      state.courses[idx].title = title;
      state.courses[idx].author = author;
      state.courses[idx].category = category;
      state.courses[idx].lessonsCount = lessons;
      state.courses[idx].rating = rating;
      showToast(`Kursus "${title}" berhasil diperbarui!`, 'success');
    }
  } else {
    // Add new
    const newId = 'crs_' + Date.now();
    let thumb = EDUFLEX_ASSETS['course-web.svg'];
    if (category === 'Design') thumb = EDUFLEX_ASSETS['course-uiux.svg'];
    if (category === 'Marketing') thumb = EDUFLEX_ASSETS['course-marketing.svg'];
    if (category === 'Business') thumb = EDUFLEX_ASSETS['course-business.svg'];

    state.courses.unshift({
      id: newId,
      title,
      author,
      category,
      rating,
      lessonsCount: lessons,
      thumb,
      desc: 'Kursus baru yang baru saja ditambahkan oleh admin.',
      isPopular: false
    });
    showToast(`Kursus baru "${title}" berhasil dipublikasikan!`, 'success');
  }

  closeAdminCourseModal();
  renderAdminCoursesTable();
  renderCatalogCourses(state.courses);
}

function deleteCourse(courseId) {
  if (confirm('Yakin ingin menghapus kursus ini dari platform?')) {
    state.courses = state.courses.filter(c => c.id !== courseId);
    renderAdminCoursesTable();
    renderCatalogCourses(state.courses);
    showToast('Kursus berhasil dihapus.', 'info');
  }
}

// ===================================================================
// MODAL 1: KUIS INTERAKTIF ENGINE
// ===================================================================
function openQuizModal() {
  state.quiz.active = true;
  state.quiz.answers = {};
  state.quiz.timerSeconds = 600;

  renderQuizQuestions();
  startQuizTimer();

  const modal = document.getElementById('quizModal');
  if (modal) modal.classList.add('show');
}

function closeQuizModal() {
  state.quiz.active = false;
  clearInterval(state.quiz.timerInterval);
  const modal = document.getElementById('quizModal');
  if (modal) modal.classList.remove('show');
}

function renderQuizQuestions() {
  const body = document.getElementById('quizModalBody');
  if (!body) return;

  body.innerHTML = '';
  state.quiz.questions.forEach((q, idx) => {
    const qBox = document.createElement('div');
    qBox.className = 'quiz-question-box';

    let optionsHtml = '';
    q.options.forEach((opt, oIdx) => {
      optionsHtml += `
        <div class="quiz-option-item" onclick="selectQuizOption(${q.id}, ${oIdx}, this)">
          <i class="fa-regular fa-circle" id="opt-icon-${q.id}-${oIdx}"></i>
          <span>${opt.text}</span>
        </div>
      `;
    });

    qBox.innerHTML = `
      <div style="font-weight:700; font-size:0.95rem; margin-bottom:12px; color:var(--text-main);">
        ${idx + 1}. ${q.question}
      </div>
      <div>${optionsHtml}</div>
    `;
    body.appendChild(qBox);
  });
}

function selectQuizOption(qId, oIdx, el) {
  state.quiz.answers[qId] = oIdx;

  // Clear previous active states in this question
  const parent = el.parentElement;
  parent.querySelectorAll('.quiz-option-item').forEach(item => {
    item.classList.remove('selected');
    const icon = item.querySelector('i');
    if (icon) icon.className = 'fa-regular fa-circle';
  });

  // Select this option
  el.classList.add('selected');
  const thisIcon = el.querySelector('i');
  if (thisIcon) thisIcon.className = 'fa-solid fa-circle-dot text-purple';
}

function startQuizTimer() {
  clearInterval(state.quiz.timerInterval);
  state.quiz.timerInterval = setInterval(() => {
    state.quiz.timerSeconds--;
    const disp = document.getElementById('quizTimerDisplay');
    if (disp) {
      const m = Math.floor(state.quiz.timerSeconds / 60);
      const s = state.quiz.timerSeconds % 60;
      disp.textContent = `${m}:${s < 10 ? '0' : ''}${s}`;
    }

    if (state.quiz.timerSeconds <= 0) {
      clearInterval(state.quiz.timerInterval);
      submitQuizAnswers();
    }
  }, 1000);
}

function submitQuizAnswers() {
  clearInterval(state.quiz.timerInterval);

  let correctCount = 0;
  const total = state.quiz.questions.length;

  state.quiz.questions.forEach(q => {
    const userSelectedIdx = state.quiz.answers[q.id];
    if (userSelectedIdx !== undefined && q.options[userSelectedIdx] && q.options[userSelectedIdx].correct) {
      correctCount++;
    }
  });

  const score = Math.round((correctCount / total) * 100);
  const isPassed = score >= 80;

  const body = document.getElementById('quizModalBody');
  const footer = document.getElementById('quizModalFooter');

  if (body) {
    body.innerHTML = `
      <div style="text-align:center; padding:30px 10px;">
        <div style="width:80px; height:80px; border-radius:50%; background:${isPassed ? 'var(--success-light)' : 'var(--danger-light)'}; color:${isPassed ? 'var(--success)' : 'var(--danger)'}; display:flex; align-items:center; justify-content:center; font-size:2.5rem; margin:0 auto 16px;">
          <i class="${isPassed ? 'fa-solid fa-trophy' : 'fa-solid fa-rotate-left'}"></i>
        </div>
        <h3 style="font-size:1.6rem; margin-bottom:8px;">${isPassed ? 'Selamat, Kamu Lulus Ujian!' : 'Belum Mencapai Nilai Minimum'}</h3>
        <p style="color:var(--text-muted); font-size:0.95rem; margin-bottom:20px;">
          ${isPassed ? 'Kamu telah menguasai seluruh konsep inti pada materi ini dengan nilai gemilang.' : 'Nilai kelulusan minimum adalah 80%. Jangan berkecil hati, kamu bisa mengulanginya!'}
        </p>

        <div style="background:#F8FAFC; border-radius:16px; padding:20px; max-width:320px; margin:0 auto 24px; border:1px solid var(--border-color);">
          <div style="font-size:0.85rem; color:var(--text-muted);">Skor Akhir</div>
          <div style="font-size:3rem; font-weight:800; color:${isPassed ? 'var(--primary)' : 'var(--danger)'};">${score} <span style="font-size:1.2rem; color:var(--text-muted);">/ 100</span></div>
          <div style="font-size:0.82rem; font-weight:600; color:var(--text-main);">${correctCount} dari ${total} pertanyaan benar</div>
        </div>
      </div>
    `;
  }

  if (footer) {
    if (isPassed) {
      footer.innerHTML = `
        <button class="btn-outline-edu" onclick="closeQuizModal()">Tutup</button>
        <button class="btn-primary-edu" onclick="closeQuizModal(); openCertificateModal('UI/UX Design Fundamentals');">
          <i class="fa-solid fa-award"></i> Ambil Sertifikat Resmi
        </button>
      `;

      // Confetti celebration
      if (typeof confetti === 'function') {
        confetti({
          particleCount: 100,
          spread: 70,
          origin: { y: 0.6 }
        });
      }
    } else {
      footer.innerHTML = `
        <button class="btn-outline-edu" onclick="closeQuizModal()">Tutup</button>
        <button class="btn-purple-edu" onclick="openQuizModal()">
          <i class="fa-solid fa-rotate-right"></i> Coba Lagi
        </button>
      `;
    }
  }
}

// ===================================================================
// MODAL 2: SERTIFIKAT GENERATOR (HTML5 CANVAS)
// ===================================================================
function openCertificateModal(courseTitle = 'UI/UX Design Fundamentals') {
  const modal = document.getElementById('certificateModal');
  if (modal) modal.classList.add('show');

  // Generate canvas certificate
  setTimeout(() => {
    drawCertificateCanvas(courseTitle);
  }, 100);
}

function closeCertificateModal() {
  const modal = document.getElementById('certificateModal');
  if (modal) modal.classList.remove('show');
}

function drawCertificateCanvas(courseName) {
  const canvas = document.getElementById('certCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');

  const width = canvas.width;
  const height = canvas.height;

  // Background
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, width, height);

  // Outer Luxury Border (Royal Navy)
  ctx.strokeStyle = '#0F172A';
  ctx.lineWidth = 14;
  ctx.strokeRect(20, 20, width - 40, height - 40);

  // Inner Gold Border
  ctx.strokeStyle = '#F59E0B';
  ctx.lineWidth = 3;
  ctx.strokeRect(32, 32, width - 64, height - 64);

  // Corner Accents
  ctx.fillStyle = '#2563EB';
  ctx.fillRect(20, 20, 40, 40);
  ctx.fillRect(width - 60, 20, 40, 40);
  ctx.fillRect(20, height - 60, 40, 40);
  ctx.fillRect(width - 60, height - 60, 40, 40);

  // Brand Name & Cap
  ctx.textAlign = 'center';
  ctx.font = 'bold 22px Poppins, sans-serif';
  ctx.fillStyle = '#2563EB';
  ctx.fillText('🎓 EDUFLEX INDONESIA', width / 2, 95);

  ctx.font = '500 13px Inter, sans-serif';
  ctx.fillStyle = '#64748B';
  ctx.fillText('LEMBAGA PENDIDIKAN & SERTIFIKASI KOMPETENSI DIGITAL', width / 2, 120);

  // Main Certificate Title
  ctx.font = '800 36px Poppins, sans-serif';
  ctx.fillStyle = '#0F172A';
  ctx.fillText('SERTIFIKAT KELULUSAN', width / 2, 185);

  ctx.font = '500 14px Inter, sans-serif';
  ctx.fillStyle = '#475569';
  ctx.fillText('Nomor Verifikasi: EDF-2026-88921 / RESMI', width / 2, 215);

  ctx.font = '400 15px Inter, sans-serif';
  ctx.fillStyle = '#64748B';
  ctx.fillText('Diberikan dengan penuh penghargaan dan kehormatan kepada:', width / 2, 260);

  // Student Name
  ctx.font = 'bold 38px Poppins, sans-serif';
  ctx.fillStyle = '#2563EB';
  ctx.fillText(state.currentUser.name, width / 2, 315);

  // Divider line under student name
  ctx.strokeStyle = '#E2E8F0';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(width / 2 - 200, 335);
  ctx.lineTo(width / 2 + 200, 335);
  ctx.stroke();

  // Completion statement
  ctx.font = '400 15px Inter, sans-serif';
  ctx.fillStyle = '#334155';
  ctx.fillText('Atas keberhasilan dan dedikasi luar biasa dalam menyelesaikan kurikulum:', width / 2, 375);

  // Course Name
  ctx.font = '700 24px Poppins, sans-serif';
  ctx.fillStyle = '#7C3AED';
  ctx.fillText(courseName, width / 2, 415);

  ctx.font = '500 13px Inter, sans-serif';
  ctx.fillStyle = '#64748B';
  ctx.fillText('Dengan Predikat: SANGAT MEMUASKAN (Grade A)', width / 2, 445);

  // Signatures Area
  const dateStr = new Date().toLocaleDateString('id-ID', { year: 'numeric', month: 'long', day: 'numeric' });

  // Left Signature: Academic Instructor
  ctx.textAlign = 'center';
  ctx.font = '600 14px Inter, sans-serif';
  ctx.fillStyle = '#0F172A';
  ctx.fillText('Andi Pratama, M.Ds.', 220, 520);
  ctx.font = '400 12px Inter, sans-serif';
  ctx.fillStyle = '#64748B';
  ctx.fillText('Instruktur Utama & Lead UI/UX', 220, 538);
  ctx.strokeStyle = '#CBD5E1';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(140, 505);
  ctx.lineTo(300, 505);
  ctx.stroke();

  // Center Gold Seal
  ctx.beginPath();
  ctx.arc(width / 2, 515, 36, 0, 2 * Math.PI);
  ctx.fillStyle = '#F59E0B';
  ctx.fill();
  ctx.strokeStyle = '#B45309';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.font = 'bold 10px Poppins, sans-serif';
  ctx.fillStyle = '#FFFFFF';
  ctx.fillText('EDUFLEX', width / 2, 512);
  ctx.fillText('VERIFIED', width / 2, 526);

  // Right Signature: Platform Director
  ctx.textAlign = 'center';
  ctx.font = '600 14px Inter, sans-serif';
  ctx.fillStyle = '#0F172A';
  ctx.fillText('Siti Aminah, Ph.D.', width - 220, 520);
  ctx.font = '400 12px Inter, sans-serif';
  ctx.fillStyle = '#64748B';
  ctx.fillText(`Direktur Akademik • ${dateStr}`, width - 220, 538);
  ctx.strokeStyle = '#CBD5E1';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(width - 300, 505);
  ctx.lineTo(width - 140, 505);
  ctx.stroke();
}

function downloadCertificatePNG() {
  const canvas = document.getElementById('certCanvas');
  if (!canvas) return;

  const link = document.createElement('a');
  link.download = `Sertifikat-EDUFLEX-${state.currentUser.name.replace(/\s+/g, '-')}.png`;
  link.href = canvas.toDataURL('image/png');
  link.click();
  showToast('Sertifikat berhasil diunduh dalam resolusi tinggi!', 'success');
}

function printCertificate() {
  const canvas = document.getElementById('certCanvas');
  if (!canvas) return;

  const dataUrl = canvas.toDataURL();
  const printWindow = window.open('', '_blank');
  printWindow.document.write(`
    <html>
      <head>
        <title>Cetak Sertifikat EDUFLEX</title>
        <style>
          body { margin: 0; display: flex; align-items: center; justify-content: center; height: 100vh; background: #FFF; }
          img { max-width: 95%; max-height: 95%; }
        </style>
      </head>
      <body>
        <img src="${dataUrl}" onload="window.print(); window.close();">
      </body>
    </html>
  `);
  printWindow.document.close();
}

// ===================================================================
// MODAL 3: AUTH LOGIC (LOGIN & REGISTER)
// ===================================================================
function openAuthModal(mode = 'login') {
  switchAuthTab(mode);
  const modal = document.getElementById('authModal');
  if (modal) modal.classList.add('show');
}

function closeAuthModal() {
  const modal = document.getElementById('authModal');
  if (modal) modal.classList.remove('show');
}

function switchAuthTab(mode) {
  const title = document.getElementById('authModalTitle');
  const regFields = document.getElementById('authRegisterFields');
  const submitBtn = document.getElementById('authSubmitBtn');
  const tabLogin = document.getElementById('authTabLogin');
  const tabRegister = document.getElementById('authTabRegister');

  if (mode === 'register') {
    if (title) title.textContent = 'Daftar Akun EDUFLEX';
    if (regFields) regFields.style.display = 'block';
    if (submitBtn) submitBtn.textContent = 'Daftar Sekarang';
    if (tabLogin) { tabLogin.classList.remove('active'); tabLogin.style.color = 'var(--text-body)'; tabLogin.style.fontWeight = '500'; }
    if (tabRegister) { tabRegister.classList.add('active'); tabRegister.style.color = 'var(--primary)'; tabRegister.style.fontWeight = '700'; }
  } else {
    if (title) title.textContent = 'Masuk ke EDUFLEX';
    if (regFields) regFields.style.display = 'none';
    if (submitBtn) submitBtn.textContent = 'Masuk Sekarang';
    if (tabRegister) { tabRegister.classList.remove('active'); tabRegister.style.color = 'var(--text-body)'; tabRegister.style.fontWeight = '500'; }
    if (tabLogin) { tabLogin.classList.add('active'); tabLogin.style.color = 'var(--primary)'; tabLogin.style.fontWeight = '700'; }
  }
}

function handleAuthSubmit(e) {
  e.preventDefault();
  const email = document.getElementById('authEmailInput').value;
  const name = document.getElementById('authNameInput') ? document.getElementById('authNameInput').value : 'Ahmad';

  if (email.includes('admin')) {
    setRoleAndSwitch('admin');
  } else {
    state.currentUser.name = name || 'Ahmad';
    state.currentUser.email = email;
    setRoleAndSwitch('siswa');
  }

  closeAuthModal();
  showToast(`Selamat datang, ${state.currentUser.name}!`, 'success');
}

function quickLoginDemo(who) {
  if (who === 'admin') {
    setRoleAndSwitch('admin');
  } else {
    setRoleAndSwitch('siswa');
  }
  closeAuthModal();
}

// ===================================================================
// TOAST NOTIFICATION UTILITY
// ===================================================================
let toastTimeout = null;
function showToast(message, type = 'info') {
  const toast = document.getElementById('eduToast');
  const msgEl = document.getElementById('toastMessage');
  const icon = document.getElementById('toastIcon');
  if (!toast || !msgEl) return;

  msgEl.textContent = message;

  if (icon) {
    if (type === 'success') {
      icon.className = 'fa-solid fa-circle-check text-success';
    } else if (type === 'danger') {
      icon.className = 'fa-solid fa-circle-exclamation text-danger';
    } else {
      icon.className = 'fa-solid fa-circle-info text-primary';
    }
  }

  toast.style.transform = 'translateY(0)';
  toast.style.opacity = '1';

  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => {
    toast.style.transform = 'translateY(100px)';
    toast.style.opacity = '0';
  }, 3500);
}
